int main() {
    int h = 9, m = 5;
    cout << setfill('0') << setw(2) << h << ':' << setw(2) << m << '\n'; // 09:05
    cout << setfill(' ');                                              // przywróć spacje
    cout << setw(6) << 42 << "|\n";            // "    42|"
    cout << left << setw(6) << 42 << "|\n";    // "42    |"
    cout << right;
    cout << setw(5) << setfill('0') << -42 << '\n';            // "00-42"  (!)
    cout << internal << setw(5) << -42 << '\n';                // "-0042"
    cout << right << setfill(' ');
    printf("%02d:%02d %5d|%-5d| %05d\n", h, m, 42, 42, -42);   // 09:05    42|42   | -0042
}

