#include <bits/stdc++.h>
using namespace std;

int main() {
    vector<int> a = {3, 1, 4, 1, 5};
    int n = a.size();

    // 1) separator przed każdym elementem poza pierwszym
    for (int i = 0; i < n; i++) {
        if (i) cout << ' ';
        cout << a[i];
    }
    cout << '\n';

    // 2) trik: " \n"[warunek] wybiera spację albo '\n'
    for (int i = 0; i < n; i++) cout << a[i] << " \n"[i == n - 1];

    // 3) tablica 2D
    vector<vector<int>> m = {{1, 2, 3}, {4, 5, 6}};
    for (auto& row : m) {
        for (int j = 0; j < (int)row.size(); j++)
            cout << row[j] << (j + 1 < (int)row.size() ? ' ' : '\n');
    }
}

