#include <bits/stdc++.h>
using namespace std;

int main() {
    int x = 10;
    cout << hex << 255 << ' ' << uppercase << 255 << nouppercase << dec << '\n'; // ff FF
    cout << oct << 8 << dec << '\n';                // 10
    cout << bitset<8>(x) << '\n';                   // 00001010
    string b = bitset<32>(x).to_string();
    b.erase(0, b.find_first_not_of('0'));           // bez zer wiodących
    if (b.empty()) b = "0";
    cout << b << '\n';                              // 1010
    cout << stoll("1010", nullptr, 2) << ' ' << stoll("ff", nullptr, 16) << '\n'; // 10 255
}

string toBase(long long x, int base) {   // x >= 0, base 2..36
    if (x == 0) return "0";
    const string digits = "0123456789abcdefghijklmnopqrstuvwxyz";
    string s;
    while (x > 0) { s += digits[x % base]; x /= base; }
    reverse(s.begin(), s.end());
    return s;
}

